		if (this._aovAlbedo) { this._aovAlbedo.dispose(); this._aovAlbedo = null; }
		if (this._aovNormal) { this._aovNormal.dispose(); this._aovNormal = null; }
		if (this._aovDepth) { this._aovDepth.dispose(); this._aovDepth = null; }
