	rObjOrigin = vec3( uRightSphereInvMatrix * vec4(rayOrigin, 1.0) );
	rObjDirection = vec3( uRightSphereInvMatrix * vec4(rayDirection, 0.0) );

	d = UnitSphereIntersect( rObjOrigin, rObjDirection, n );

