                	TP = Tr / (1.0 - P);

			if (diffuseCount == 0 && blueNoise_rand() < P)
			{
				mask *= RP;
				rayDirection = reflect(rayDirection, nl); // reflect ray from surface
				rayOrigin = x + nl * uEPS_intersect;
				continue;
			}

